// Root_of_Trust_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module Root_of_Trust_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [1:0] c_cmd_op,
  input logic [5:0] c_cmd_addr,
  input logic [31:0] c_cmd_data,
  input logic [127:0] c_token,
  input logic  c_cmd_start,
  input logic [31:0] c_img_data,
  input logic  c_img_last,
  input logic [31:0] c_cmd_rdata,
  input logic  c_cmd_busy,
  input logic  c_init_done,
  input logic [2:0] c_lc_state,
  input logic  c_boot_ok,
  input logic  c_cpu_en,
  input logic  c_dbg_en,
  input logic  c_key_valid,
  input logic [2:0] c_alert_code,
  input logic  c_img_valid,
  input logic  c_img_ready,
  input logic  c_cmd_done,
  input logic  c_cmd_err,
  input logic  c_boot_done,
  input logic  c_alert
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 16;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:15];          // model of every stored word
  logic [5:0] m_set;                // interrupt bits set this clock
  logic [31:0] m_pulse_CMD;
  logic m_state_IMG;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_cmd_done) m_set[0] = 1'b1;
    if (c_cmd_err) m_set[1] = 1'b1;
    if (c_boot_done) m_set[2] = 1'b1;
    if (c_alert) m_set[3] = 1'b1;
    if (m_state_IMG && c_img_ready) m_set[4] = 1'b1;
    if (m_wr && m_map && (m_idx == 12 || m_idx == 13) && m_state_IMG) m_set[5] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_pulse_CMD <= 0;
      m_state_IMG <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3F;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 6) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      m_pulse_CMD <= (m_wr && m_map && m_idx == 11) ? PWDATA & m_be & 32'h1 : 0;
      if (m_wr && m_map && m_idx == 12 && !m_state_IMG) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13 && !m_state_IMG) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 13 && !m_state_IMG) m_state_IMG <= 1;
      if (m_state_IMG && c_img_ready) m_state_IMG <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h52540100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_IMG});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return 0;
      12: return m_w[12];
      13: return m_w[13];
      14: return (32'(c_cmd_rdata) << 0);
      15: return (32'(c_cmd_busy) << 0) | (32'(c_init_done) << 1) | (32'(c_lc_state) << 2) | (32'(c_boot_ok) << 5) | (32'(c_cpu_en) << 6) | (32'(c_dbg_en) << 7) | (32'(c_key_valid) << 8) | (32'(c_alert_code) << 9);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][5:0] & m_w[2][5:0]))
  `SVA_INV(a_core_cmd_op, c_cmd_op == m_w[5][1:0])
  `SVA_INV(a_core_cmd_addr, c_cmd_addr == m_w[5][7:2])
  `SVA_INV(a_core_cmd_data, c_cmd_data == m_w[6][31:0])
  `SVA_INV(a_core_token_31_0, c_token[31:0] == m_w[7][31:0])
  `SVA_INV(a_core_token_63_32, c_token[63:32] == m_w[8][31:0])
  `SVA_INV(a_core_token_95_64, c_token[95:64] == m_w[9][31:0])
  `SVA_INV(a_core_token_127_96, c_token[127:96] == m_w[10][31:0])
  `SVA_INV(a_core_cmd_start, c_cmd_start == m_pulse_CMD[0])
  `SVA_INV(a_core_img_data, c_img_data == m_w[12][31:0])
  `SVA_INV(a_core_img_last, c_img_last == m_w[13][0:0])
  `SVA_INV(a_core_img_valid, c_img_valid == m_state_IMG)
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cmd_op == 2'h0 && c_cmd_addr == 6'h0 && c_cmd_data == 32'h0 && c_token[31:0] == 32'h0 && c_token[63:32] == 32'h0 && c_token[95:64] == 32'h0 && c_token[127:96] == 32'h0 && c_cmd_start == 1'h0 && c_img_data == 32'h0 && c_img_last == 1'h0 && !c_img_valid)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CTRL, m_rd && m_map && m_idx == 5)
  `FC(wr_CTRL, m_wr && m_map && m_idx == 5)
  `FC(rd_CMD_DATA, m_rd && m_map && m_idx == 6)
  `FC(wr_CMD_DATA, m_wr && m_map && m_idx == 6)
  `FC(rd_TOKEN0, m_rd && m_map && m_idx == 7)
  `FC(wr_TOKEN0, m_wr && m_map && m_idx == 7)
  `FC(rd_TOKEN1, m_rd && m_map && m_idx == 8)
  `FC(wr_TOKEN1, m_wr && m_map && m_idx == 8)
  `FC(rd_TOKEN2, m_rd && m_map && m_idx == 9)
  `FC(wr_TOKEN2, m_wr && m_map && m_idx == 9)
  `FC(rd_TOKEN3, m_rd && m_map && m_idx == 10)
  `FC(wr_TOKEN3, m_wr && m_map && m_idx == 10)
  `FC(rd_CMD, m_rd && m_map && m_idx == 11)
  `FC(wr_CMD, m_wr && m_map && m_idx == 11)
  `FC(rd_IMG0, m_rd && m_map && m_idx == 12)
  `FC(wr_IMG0, m_wr && m_map && m_idx == 12)
  `FC(rd_IMG1, m_rd && m_map && m_idx == 13)
  `FC(wr_IMG1, m_wr && m_map && m_idx == 13)
  `FC(rd_RDATA, m_rd && m_map && m_idx == 14)
  `FC(wr_RDATA, m_wr && m_map && m_idx == 14)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 15)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 15)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_CMD_DONE_set, m_set[0])
  `FC(irq_CMD_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_CMD_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_CMD_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_CMD_ERR_set, m_set[1])
  `FC(irq_CMD_ERR_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_CMD_ERR_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_CMD_ERR_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_BOOT_set, m_set[2])
  `FC(irq_BOOT_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_BOOT_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_BOOT_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_ALERT_set, m_set[3])
  `FC(irq_ALERT_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_ALERT_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_ALERT_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_IMG_DONE_set, m_set[4])
  `FC(irq_IMG_DONE_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_IMG_DONE_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_IMG_DONE_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_IMG_OVF_set, m_set[5])
  `FC(irq_IMG_OVF_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_IMG_OVF_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_IMG_OVF_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(cmd_cmd_start, m_pulse_CMD[0])
  `FC(IMG_handshake, m_state_IMG && c_img_ready)
  `FC(IMG_backpressure, m_state_IMG && !c_img_ready)
  `FC(IMG_write_while_full, m_wr && m_map && m_idx == 13 && m_state_IMG)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind Root_of_Trust_apb Root_of_Trust_apb_sva u_apb_sva (.*);
